from datetime import date
from typing import List, Tuple

def reconcile(bank: List[Tuple[str, str, float]],
              ledger: List[Tuple[str, str, float]],
              window: int = 2
              ) -> Tuple[List[Tuple[str, str]], List[str], List[str]]:

    def parse(d):
        return date.fromisoformat(d)

    # Keep original order references for unmatched output
    bank_order = [b[0] for b in bank]
    ledger_order = [l[0] for l in ledger]

    # Sort bank items by (date, id)
    bank_sorted = sorted(bank, key=lambda x: (parse(x[1]), x[0]))

    ledger_matched = set()
    bank_matched = set()
    matches = []

    # Precompute ledger list with parsed dates for quick access
    ledger_info = {l[0]: (parse(l[1]), l[2]) for l in ledger}

    for b_id, b_date_str, b_amount in bank_sorted:
        b_date = parse(b_date_str)
        best_candidate = None  # (ledger_date, ledger_id)

        for l_id, (l_date, l_amount) in ledger_info.items():
            if l_id in ledger_matched:
                continue
            if l_amount != b_amount:
                continue
            diff = abs((b_date - l_date).days)
            if diff > window:
                continue
            candidate_key = (l_date, l_id)
            if best_candidate is None or candidate_key < best_candidate:
                best_candidate = candidate_key

        if best_candidate is not None:
            chosen_l_id = best_candidate[1]
            ledger_matched.add(chosen_l_id)
            bank_matched.add(b_id)
            matches.append((b_id, chosen_l_id))

    unmatched_bank = [bid for bid in bank_order if bid not in bank_matched]
    unmatched_ledger = [lid for lid in ledger_order if lid not in ledger_matched]

    return (matches, unmatched_bank, unmatched_ledger)
